import { useState } from "react";
import { useDispatch, useSelector } from "react-redux";

import {Button} from "antd";
import {web3ConnectEther} from "../../actions";

const BtnConnect = ({ onChangeWallet, getLocalWallet }) => {
    const [isConnecting, setIsConnecting] = useState(false);
    const dispatch = useDispatch();
    const [account] = useSelector(({web3})=>[web3.account])
    let keyWallet = "metamask";

    const connectWalletHandler = async () => {
        if (!isConnecting) {
            setIsConnecting(true);
            await dispatch(web3ConnectEther())
                .then((res) => {
                    setIsConnecting(false);
                    if (res) {
                        onChangeWallet(keyWallet);
                    }
                })
                .catch((e) => {
                    setIsConnecting(false);
                });
        }
    };

    return (
        <Button
            onClick={connectWalletHandler}
            loading={isConnecting}
            disabled={!!account}
            type={"primary"}
        >
            {account ? `${account.slice(0, 6)}...${account.slice(account.length-6, account.length)}` : "Connect wallet"}
        </Button>
    );
};

export default BtnConnect;
