import {message} from 'antd'
import {toast} from "react-toastify";

export const showMessageError = (...args) => {
    return toast.error(...args)
}
const getToken = async () => {
    try {
        if (localStorage) {
            return await localStorage.getItem('token_code')
        }
    } catch (e) {
        console.error(e)
    }
    return null
}
const fetching = (url, payload, callbackFun, raw=false) =>
    // eslint-disable-next-line no-async-promise-executor
    new Promise(async (resolve, reject) => {
        try {
            let {method = 'GET', params, body, headers = {}, url_params, files} = payload
            let _headers = {
                Accept: 'application/json',
                'Content-Type': 'application/json',
            }
            const token = await getToken()
            if (token) {
                _headers['Authorization'] = `Bearer ${token}`
            }
            let _reqOptions = {
                method,
                headers: _headers,
                // 'mode': 'no-cors'

            }
            if (headers['Content-Type'] === 'multipart/form-data') {
                delete _reqOptions.headers['Content-Type']
                const formData = new FormData()
                if (files) {
                    formData.append('file', files[0], files[0].renameFile || files[0].name)
                }
                _reqOptions.body = formData
            } else {
                if (body) {
                    _reqOptions.body = await JSON.stringify({...body})
                }
            }

            let query = '1=1'
            if (params) {
                for (const _p_key in params) {
                    query = `${query}&${_p_key}=${params[_p_key]}`
                }
            }
            let _url = `${url}?${query}`
            // if (process.env.DEBUG && url.indexOf('merchant/') === -1) {
            //   _url = `https://api-staging.thecuatui.net/v1/${url}?${query}`
            // } else {
            //   _url = `${process.env.API}${url}?${query}`
            // }
            if (url_params) {
                Object.keys(url_params).map((v) => {
                    _url = _url.replace(v, url_params[v])
                })
            }

            // eslint-disable-next-line no-undef
            if (process.env.DEBUG) {
                console.log('DEBUG [API]', _url)
                console.log(_reqOptions)
            }
            const response = await fetch(_url, _reqOptions)

            if (response && response.status === 200) {
                const response_json = await response.json()
                if(raw) {
                    return resolve(response_json)
                }
                // eslint-disable-next-line no-undef
                console.log('DEBUG [RESPONSE]', _url)
                if (!response_json.data) {
                    showMessageError(
                        response_json.msg || 'Internal server error!',
                    )
                    return reject()
                } else {
                    if (callbackFun) callbackFun()
                    return resolve(response_json.data || {})
                }
            } else {
                showMessageError('Internal server error!')
            }
            return reject()
        } catch (e) {
            console.error(e)
            showMessageError('Hệ thống lỗi', 5)
            return reject()
        }
    })
export default fetching
