const _initState = {
}

export const SET_PRICE = 'SET_PRICE'
export const SET_PRICE_LOADING = 'SET_PRICE_LOADING'

const _handlers = {
    [SET_PRICE]: (state, payload) => ({
        ...state,
        prices: payload.prices,
        loading: false
    }),
    [SET_PRICE_LOADING]: (state, payload) => ({
        ...state,
        loading: payload.loading
    })
}

export default (state = _initState, action) => {
    let _handler = action.type && _handlers[action.type]
    return _handler ? _handler(state, action.payload) : state
}