import {call, takeEvery, put, select} from 'redux-saga/effects'
import fetching, {showMessageError} from './fetching'
import {setLoading, setPrice} from "../actions/price";
import {getPrice} from "../services/dapp";

export const SAGA_FETCH_PRICE = 'SAGA_FETCH_PRICE'

function* _fetchPrice(action) {

    try {
        const [loading] = yield select(({price}) => [price?.loading])
        if (!loading) {
            yield put(setLoading(true))
            const response = yield call(fetching, getPrice, {
                params: {
                    'vs_currency': 'usd',
                    ids: 'binancecoin,tether,wbnb'
                }
            }, null, true)
            console.log(response)
            yield put(setPrice(response))
        }

    } catch (e) {
        yield call(showMessageError, 'Internal server error!')
        yield put(setLoading(false))

    }

}

export default function* () {
    yield takeEvery(SAGA_FETCH_PRICE, _fetchPrice)
}
