import {ADD_COLLECTION, SET_LOADING} from "../reducers/royalty";

export const setCollections = ({collection_nft = [], collection_box = [], overview={}, withdraw_history=[], token_address={}}) => ({
    type: ADD_COLLECTION,
    payload: {
        collections: [
            ...collection_nft, ...collection_box
        ],
        overview,
        withdraw_history,
        token_address
    }
})
export const setLoading = (loading) => ({
    type: SET_LOADING,
    payload: {
        loading
    }
})
