import { createStore, applyMiddleware, compose } from 'redux';
import createSagaMiddleware, { END } from 'redux-saga'
import rootReducer from './reducers'
import thunk from 'redux-thunk';
import promise from 'redux-promise';
import logger from 'redux-logger';
import rootSaga from './saga'
const sagaMiddleware = createSagaMiddleware()

var middlewares = [];
middlewares.push(thunk);
middlewares.push(promise);


// let middlewareThunk = applyMiddleware(...middlewares);


let devTools;
if (process.env.NODE_ENV === 'prod' || process.env.NODE_ENV === 'production') {
    devTools = a => a;
} else {
    // middlewareThunk = applyMiddleware(thunk, logger)
    middlewares.push(logger)
    devTools = window.__REDUX_DEVTOOLS_EXTENSION_COMPOSE__ ? window.__REDUX_DEVTOOLS_EXTENSION__ && window.__REDUX_DEVTOOLS_EXTENSION__() : compose
}

const bindMiddleware = (middleware) => {
    return applyMiddleware(...middleware)
}
function configureStore(initialState = {}) {
    const store = createStore(
        rootReducer,
        initialState,
        compose(bindMiddleware([...middlewares, sagaMiddleware]), devTools),
    )

    store.runSaga = () => {
        // Avoid running twice
        if (store.saga) return
        store.saga = sagaMiddleware.run(rootSaga)
    }

    store.stopSaga = async () => {
        // Avoid running twice
        if (!store.saga) return
        store.dispatch(END)
        await store.saga.done
        store.saga = null
    }

    store.execSagaTasks = async (isServer, tasks) => {
        // run saga
        store.runSaga()
        // dispatch saga tasks
        tasks(store.dispatch)
        // Stop running and wait for the tasks to be done
        await store.stopSaga()
        // Re-run on client side
        if (!isServer) {
            store.runSaga()
        }
    }

    // Initial run
    store.runSaga()

    return store
}
export const store = configureStore()