import React, {useEffect, useState} from "react";
import {Modal, Button, Col, Input, Row, Table, Form, Select, Spin} from "antd";
import {getStatic} from "../utils/static";
import {useDispatch, useSelector} from "react-redux";
import {SAGA_FETCH_ROYALTY} from "../saga/royalty";
import {SAGA_FETCH_PRICE} from "../saga/price";
import {royaltySmartContract} from "../chain/evm/contract";
import {toast} from "react-toastify";

const {Option} = Select;

const Home = () => {
    const dispatch = useDispatch()
    const [royalty, web3] = useSelector(({royalty, web3}) => [royalty, web3])
    const [col, setCol] = useState(false)
    const [sign, setSign] = useState(false)
    const withdrawCol = (record) => {
        setCol(record)
    }
    const columns = [{
        title: 'Cover',
        dataIndex: 'name',
        key: 'name',
        render: (item, record) => {
            console.log(record)
            return (<div className={"collection-info"}>
                {/*<Avatar size="middle" src={"https://i.pravatar.cc/300"}>*/}
                {/*</Avatar>*/}
                <span>{"  "} {record.name} </span>
            </div>)
        }, fixed: 'left',
    }, {
        title: 'Total Income', dataIndex: 'primary_sale', key: 'primary_sale',
        render: (_, record) => `${Math.round(record?.primary_sale?.balance)} ${record?.primary_sale?.symbol}`
    }, {
        title: 'Primary Sales', dataIndex: 'address', key: 'address',
        render: (_, record) => `${Math.round(record?.primary_sale?.balance)} ${record?.primary_sale?.symbol}`
    }, {
        title: 'Royalty', dataIndex: 'royalty', key: 'royalty',
        render: (_, record) => `${record.royalty} USD`

    }, {
        title: ' ', key: 'action', render: (_, record) => (<Button
            onClick={_ => withdrawCol(record)}
            className={"btn_claim"}>Claim</Button>)
    },];

    const getInfo = async () => {
        try {
            dispatch({
                type: SAGA_FETCH_PRICE
            })
            dispatch({
                type: SAGA_FETCH_ROYALTY,
                payload: {
                    params: {
                        address: web3?.account
                    }
                }
            })
        } catch (e) {
            console.error(e)
        }
    }
    useEffect(() => {
        if (web3?.account) {
            getInfo()
        }
    }, [web3.account])
    const convertData = (timestamp) => {
        const date = new Date(timestamp * 1000);
        return date.getHours() + ":" + date.getMinutes() + ", " + date.toDateString();
    }

    const handleCancel = () => {
        setCol(false)
    }

    const onFinish = async (values) => {
        setSign(true)
        console.log(values);
        try {
            let smc = await royaltySmartContract(web3.web3)
            console.log(smc)
            await smc.methods.withdraw(
                web3.web3.utils.toChecksumAddress(values['token']),
                web3.web3.utils.toWei(values['amount']),
                web3.web3.utils.toChecksumAddress(col.address),
            ).send({
                from: web3.account
            }).on('transactionHash', function (hash) {
                console.log("hash", hash)
                toast.success(`Tx: ${hash}`)
            }).on('receipt', function (receipt) {
                console.log("receipt", receipt)
                setSign(false);
            })
                .on('confirmation', function (confirmationNumber, receipt) {
                    console.log(confirmationNumber)
                })
                .on('error', e => toast.error(e.toString())).catch(e => toast.error(e.toString()));
        } catch (e) {
            console.error(e)
            toast.error(e.toString())
            // setSign(false)

        }
    };
    return <div className="main">
        <Modal title="Claim" open={col} footer={null} onCancel={handleCancel}>
            <Spin spinning={sign} tip={"Sign..."}>

                <Form onFinish={onFinish}>
                    <Form.Item name="token" label="Token" rules={[{required: true}]}>

                        <Select style={{
                            width: "100%"
                        }}>
                            {
                                Object.keys(royalty.token_address).map(_token => <Option
                                    value={royalty.token_address[_token]}>{_token}</Option>)
                            }
                        </Select>
                    </Form.Item>
                    <Form.Item
                        label="Amount"
                        name="amount"
                        rules={[{required: true, message: 'Please input your username!'}]}
                    >
                        <Input/>
                    </Form.Item>
                    <Form.Item>
                        <Button type="primary" htmlType="submit">
                            Sign
                        </Button>
                    </Form.Item>
                </Form>
            </Spin>

        </Modal>

        <div className="home-page page">
            <div className={"title"}>
                <h3>Collections income</h3>
                {
                    web3?.account &&
                    <span>Last Update Today, {royalty?.withdraw_history?.length > 0 ? convertData(royalty?.withdraw_history[0].block_time) : 'N/A'}</span>

                }
            </div>
            <div className={"page-body"}>
                <Row gutter={[16, 31]} justify={"space-between"}>
                    <Col {...{xs: 24, sm: 24, md: 16, lg: 16}} flex={"auto"}>
                        <div className={"card"}>
                            <div className={"card-header"}>
                                <img src={getStatic("assets/images/icons/wallet.svg")} loading={"lazy"}/>
                                <div className={"f-right"}>
                                    <img src={getStatic("assets/images/icons/upByDay.svg")}/>
                                    <span
                                        className={"up-by-day"}>${royalty?.overview?.total_income?.toFixed(3)}</span>
                                    <i>Today</i>
                                </div>
                            </div>
                            <div>

                            </div>
                            <div>
                                <Row gutter={[16, 16]}>
                                    <Col {...{xs: 24, sm: 24, md: 7, lg: 7}}>
                                        <div className={"title"}>
                                            <p className={"value-income"}>${royalty?.overview?.total_income?.toFixed(3)}</p>
                                            <span>My Balance</span>
                                        </div>
                                    </Col>
                                    <Col {...{xs: 12, sm: 12, md: 6, lg: 6}}>
                                        <div className={'row'}>
                                            <div className={"royalty-value"}>
                                                <img src={getStatic("assets/images/icons/run-left.svg")}/>
                                                <div>
                                                    <p>
                                                        ${royalty?.overview?.total_primary_sale?.toFixed(3)}
                                                    </p>
                                                    <span>
                                                        Primary Sales
                                                    </span>
                                                </div>
                                            </div>

                                        </div>
                                    </Col>
                                    <Col {...{xs: 12, sm: 12, md: 6, lg: 6}}>
                                        <div className={'row'}>
                                            <div className={"royalty-value"}>
                                                <img src={getStatic("assets/images/icons/run-left.svg")}/>
                                                <div>
                                                    <p>
                                                        ${royalty?.overview?.total_royalty?.toFixed(3)}
                                                    </p>
                                                    <span>
                                                        Primary Sales
                                                    </span>
                                                </div>
                                            </div>
                                        </div>
                                    </Col>
                                    <Col {...{xs: 24, sm: 24, md: 5, lg: 5}}>
                                        <div className={"row royalty-value "} style={{width: "100%"}}>
                                            <div className={"f-right royalty-btn"} style={{margin: "inherit"}}>
                                                <Button className={"withdraw"}>
                                                    Withdraw
                                                </Button>
                                            </div>
                                        </div>
                                    </Col>
                                </Row>
                            </div>
                        </div>
                    </Col>
                    <Col {...{xs: 24, sm: 24, md: 8, lg: 8}} flex={"auto"}>
                        <div className={"card"}>
                            <div>
                                <img src={getStatic("assets/images/icons/growUp.svg")}/>
                                <div className={"f-right "}>
                                    <img src={getStatic("assets/images/icons/upByDay.svg")}/>
                                    <span className={"up-by-day"}>
                                                ${royalty?.overview?.total_income?.toFixed(3)}
                                    </span>
                                    <i>Today</i>
                                </div>
                            </div>
                            <div className={"value-income-right"}>
                                <h3 className={"value-income "}>
                                    ${royalty?.overview?.total_primary_sale?.toFixed(3)}
                                </h3>
                                <span>Total  Collection Primary Sales</span>
                            </div>
                        </div>
                    </Col>
                    <Col {...{xs: 24, sm: 24, md: 16, lg: 16}}>
                        <div className={"card"}>
                            <div className={""}></div>
                            <div className={"table-header"}>
                                <h3 className={"table-title"} style={{
                                    maxWidth: 500
                                }}>{royalty.collections?.length} collections</h3>
                                <div className={'f-search'}>
                                    <Input placeholder="Search by collection name"
                                        // enterButton={null}
                                           rootClassName={"input-search"}
                                           addonBefore={<img src={getStatic("assets/images/icons/search.svg")}/>}/>

                                </div>
                            </div>

                            <div>
                                <Table
                                    pagination={false}
                                    scroll={{
                                        x: 500,
                                    }}
                                    dataSource={royalty.collections} columns={columns}/>
                            </div>
                        </div>
                    </Col>
                    <Col {...{xs: 24, sm: 24, md: 8, lg: 8}}>
                        <div className={"card"}>
                            <h3 className={"table-title"}>Withdraw History</h3>
                            <div>
                                <Table
                                    pagination={false}

                                    dataSource={royalty?.withdraw_history || []}
                                    columns={[{
                                        title: ' ',
                                        dataIndex: 'name',
                                        key: 'name',
                                        render: (_, record) => (<div key={record.tx_hash} className={"withdraw-info"}>
                                            <h4>Withdraw</h4>
                                            <span>{record?.block_time ? convertData(record?.block_time) : 'N/A'}</span>
                                        </div>),
                                    }, {
                                        title: ' ',
                                        dataIndex: 'amount',
                                        key: 'amount',
                                        render: (_, record) => (<span style={{
                                            textAlign: "end"
                                        }}>-${record?.amount?.toFixed(3)}</span>)
                                    },]}/>
                            </div>
                        </div>
                    </Col>
                </Row>
                <Row gutter={[16, 16]}>

                </Row>
            </div>
        </div>
    </div>
}
export default Home