import {web3Constants} from "../constants";

const initState = {
    web3: null,
    account: ''
}

const handlers = {
    [web3Constants.WEB3_CONNECT]: (state, payload) => ({
        ...state,
        connex: payload.connex,
        account: payload.account,
        web3: payload.web3
    }),
    [web3Constants.WEB3_DISCONNECT]: (state, payload) => ({
        ...state,
        connex: null,
        account: null,
        web3: null
    })
}
export default (state = initState, action) => {
    let _handler = action.type && handlers[action.type]
    console.log(_handler)
    return _handler ?  _handler(state, action.payload)  : state
}