import {call, takeEvery, put, select} from 'redux-saga/effects'
import fetching, {showMessageError} from './fetching'
import {getRoyalty} from "../services";
import {setCollections, setLoading} from "../actions/royalty";

export const SAGA_FETCH_ROYALTY = 'SAGA_FETCH_ROYALTY'

function* _fetchRoyalty(action) {

    try {
        const {params} = action.payload
        const [loading] = yield select(({royalty}) => [royalty?.loading])
        if (!loading) {
            yield put(setLoading(true))
            const response = yield call(fetching, getRoyalty, {
                params: params
            })
            console.log(response)
            yield put(setCollections(response))
        }

    } catch (e) {
        // yield call(showMessageError, 'Internal server error!')
        yield put(setLoading(false))

    }

}

export default function* () {
    yield takeEvery(SAGA_FETCH_ROYALTY, _fetchRoyalty)
}
