const _initState = {
    collections: [], histories: [], overview: {}, token_address:{}
}

export const ADD_COLLECTION = 'ADD_COLLECTION'
// export const ADD_HISTORIES = 'ADD_HISTORIES'
export const SET_LOADING = 'SET_LOADING'

const _handlers = {
    [ADD_COLLECTION]: (state, payload) => ({
        ...state,
        collections: payload.collections,
        overview: payload.overview,
        loading: false,
        withdraw_history: payload.withdraw_history,
            token_address: payload.token_address
    }),
    [SET_LOADING]: (state, payload) => ({
        ...state,
        loading: payload.loading
    })
}

export default (state = _initState, action) => {
    let _handler = action.type && _handlers[action.type]
    return _handler ? _handler(state, action.payload) : state
}